            with tab_supl:
                st.markdown("### 💊 Guia de Suplementação")
                obj_supl = st.selectbox("Objetivo:", ["Emagrecer","Ganhar massa muscular","Energia e disposição","Saúde geral","Performance esportiva","Sono e recuperação"], key="chefcalo59")
