        def pegar(chave, texto):
            pat = rf"{chave}:\\s*(.+?)(?=\\n[A-Z_]{{3,}}:|$)"
            m = _re.search(pat, texto, _re.DOTALL)
            return m.group(1).strip() if m else ""

